<?php if(!defined('APP_ENTRY'))exit; if($_SERVER['REQUEST_METHOD']==='POST')try{$action=post('action');$sid=id_field('student_id');$s=one('SELECT id FROM students WHERE id=?',[$sid]);if(!$s)missing();transaction(function()use($action,$sid){$a=one('SELECT id,active FROM student_accounts WHERE student_id=? FOR UPDATE',[$sid]);if($action==='invite'){if($a)throw new DomainException('This student already has an account.');$code=bin2hex(random_bytes(16));execute('UPDATE students SET invite_hash=?,invite_expires=DATE_ADD(NOW(),INTERVAL 1 DAY) WHERE id=?',[hash('sha256',$code),$sid]);audit('issue activation code',"student #$sid");flash('One-time code (valid 24 hours): '.$code.' — share privately with the student.');}elseif($action==='reset'){if(!$a)throw new DomainException('Activate the account first.');execute('UPDATE student_accounts SET password_hash=?,session_version=session_version+1 WHERE id=?',[password_hash(password_field(),PASSWORD_DEFAULT),$a['id']]);audit('reset student password',"student #$sid");flash('Password reset.');}elseif($action==='toggle'){if(!$a)throw new DomainException('Account not found.');execute('UPDATE student_accounts SET active=1-active,session_version=session_version+1 WHERE id=?',[$a['id']]);audit('toggle student account',"student #$sid");flash('Account status updated.');}else deny();});redirect('accounts');}catch(DomainException $ex){$error=$ex->getMessage();}catch(PDOException $ex){error_log_file($ex);$error='Unable to update the account.';}
$q='%'.search_term().'%';$data=rows('SELECT s.id,s.name,s.email,a.username,a.active FROM students s LEFT JOIN student_accounts a ON a.student_id=s.id WHERE s.name LIKE ? OR s.email LIKE ? ORDER BY s.name',[$q,$q]); ?>
<?php if($error):?><div class="error"><?=e($error)?></div><?php endif;?><section class="panel"><p class="muted">Students activate their own accounts using a one-time code. Staff accounts are managed separately. Existing accounts can be disabled or reset.</p><div class="toolbar"><h2>Student access</h2><?php search_form($page);?></div><div class="table-wrap"><table><thead><tr><th>Student</th><th>Username</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($data as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['username']??'—')?></td><td><?=e($r['username']===null?'Not activated':($r['active']?'Active':'Inactive'))?></td><td><?php if($r['username']===null):?><form method="post"><?=csrf_field()?><input type="hidden" name="student_id" value="<?=$r['id']?>"><button name="action" value="invite">Issue activation code</button></form><?php else:?><form method="post" class="inline"><?=csrf_field()?><input type="hidden" name="student_id" value="<?=$r['id']?>"><button class="secondary" name="action" value="toggle"><?=$r['active']?'Disable':'Enable'?></button></form><form class="inline spaced" method="post"><?=csrf_field()?><input type="hidden" name="student_id" value="<?=$r['id']?>"><input type="password" name="password" placeholder="New password" minlength="10" maxlength="72" required><button name="action" value="reset">Reset password</button></form><?php endif;?></td></tr><?php endforeach;?><?php if(!$data):?><tr><td colspan="4">No students found.</td></tr><?php endif;?></tbody></table></div></section>
